 race? Your time and rewards will not count.'))return;running=false;cancelAnimationFrame(raf);screen='garage';$('#raceScreen').classList.add('hidden');$('#garageScreen').classList.remove('hidden')};$('#soundBtn').onclick=()=>{state.muted=!state.muted;save();toast(state.muted?'Sound disabled':'Sound enabled · (engine audio coming soon)')};$$('[data-steer]').forEach(b=>{let n=+b.dataset.steer;b.addEventListener('pointerdown',e=>{e.preventDefault();steerBy(n)})});$$('[data-boost]').forEach(b=>{b.addEventListener('pointerdown',e=>{e.preventDefault();boosting=true});['pointerup','pointerleave','pointercancel'].forEach(ev=>b.addEventListener(ev,()=>boosting=false))});
